"""One-shot transport of locally tested source edits. CI records the actual source."""
from pathlib import Path
import base64, hashlib, subprocess, zlib, zipfile
PAYLOAD = (
""
""
)
patch = zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(patch).hexdigest() == '59cf9a5ccb5b459d87ac7ec255efea0d7c8fcc093bf7f190fe16ccb1bd19c6a2', 'Transport checksum mismatch'
for line in patch.decode().splitlines():
    if line.startswith('--- a/'):
        path = Path(line[6:])
        path.write_text(path.read_text(encoding='utf-8'), encoding='utf-8', newline='\n')
subprocess.run(['git', 'apply', '--check', '--whitespace=nowarn', '-'], input=patch, check=True)
subprocess.run(['git', 'apply', '--whitespace=nowarn', '-'], input=patch, check=True)
Path('release').mkdir(exist_ok=True)
with zipfile.ZipFile('release/review-source.zip', 'w', zipfile.ZIP_DEFLATED) as archive:
    for folder in ['src', 'tests', 'docs', '.github', 'scripts']:
        for path in Path(folder).rglob('*'):
            if path.is_file() and not any(p in path.parts for p in ['bin', 'obj', '__pycache__', 'ux-patches']): archive.write(path, path.as_posix())
    for name in ['Directory.Build.props', 'Directory.Packages.props', 'MyLovePixel.slnx', 'global.json', 'HANDOFF.md', 'README.md', 'THIRD_PARTY_NOTICES.md']:
        archive.write(name)
